(function(){
"use strict";

/* ===================================================================
   CLIENT VIEW LAYER
   Identical rendering to the validated prototype, but the state now
   arrives from the server over Socket.IO. The client never decides a
   rule and never owns the clock: it renders what the server says and
   sends intents back.
   =================================================================== */

var SOCKET = io({ transports: ["websocket", "polling"] });

var MAP_IMAGES = {"luxville":"data:image/jpeg;base64,","storm_tube":"data:image/jpeg;base64,","new_midtown":"data:image/jpeg;base64,","blow_city":"data:image/jpeg;base64,","broken_alley":"data:image/jpeg;base64,","secret_mansion":"data:image/jpeg;base64,","roadside":"data:image/jpeg;base64,","sand_storm":"data:image/jpeg;base64,","airport":"data:image/jpeg;base64,"};

var CONST = {
  TURN_SECONDS: 60, WARN_AT: 10, DANGER_AT: 5,
  EXPECTED_REMAINING: { BO3: 4, BO5: 4 },
  ROLES: {
    SUPER_ADMIN:{label:"SUPER ADMIN"}, TOURNAMENT_ADMIN:{label:"TOURNAMENT ADMIN"},
    REFEREE:{label:"REFEREE"}, CAPTAIN_A:{label:"TEAM A CAPTAIN"}, CAPTAIN_B:{label:"TEAM B CAPTAIN"},
    PUBLIC:{label:"PUBLIC VIEWER"}, OBS:{label:"OBS / BROADCAST"}
  }
};

var state = null;          // last match state from the server
var serverOffset = 0;      // serverTime - clientTime, so every device counts the same
var connected = false;

function S(){ return state; }

/* selectors mirror src/rules.js — display only, never decisions */
var sel = {
  teamName: function(t){
    if(t === "REFEREE") return "REFEREE";
    if(!state) return "—";
    return t === "A" ? state.teamA.name : (t === "B" ? state.teamB.name : "SYSTEM");
  },
  mapById: function(id){ return state ? (state.mapPool.filter(function(m){ return m.id === id; })[0] || null) : null; },
  available: function(){ return state ? state.mapPool.filter(function(m){ return m.status === "AVAILABLE"; }) : []; },
  stepDef: function(){
    if(!state || !state.sequence.length || state.currentStep < 1) return null;
    return state.sequence[state.currentStep - 1] || null;
  },
  gamesCount: function(){ return state && state.format === "BO5" ? 5 : 3; },
  roleCanReferee: function(r){ return r === "REFEREE" || r === "SUPER_ADMIN"; }
};

/* the engine shim keeps the proven view code unchanged */
var engine = {
  ROLES: CONST.ROLES,
  TURN_SECONDS: CONST.TURN_SECONDS,
  WARN_AT: CONST.WARN_AT,
  DANGER_AT: CONST.DANGER_AT,
  EXPECTED_REMAINING: CONST.EXPECTED_REMAINING,
  sel: sel,
  getState: S
};

var ui = {
  role: "PUBLIC",
  roomId: null,
  token: null,
  coinSpin: null,
  rolling: false
};

var app       = document.getElementById("app");
var statusHost= document.getElementById("statusHost");
var toastHost = document.getElementById("toastHost");

/* remaining time is always derived from the server's deadline */
function remainingMs(){
  if(!state || !state.timer || !state.timer.running || !state.timer.endsAt) return 0;
  return Math.max(0, state.timer.endsAt - (Date.now() + serverOffset));
}

/* ---------- small helpers ---------- */
function esc(s){ return String(s == null ? "" : s).replace(/[&<>"']/g, function(c){
  return ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"})[c]; }); }
function pad2(n){ return (n < 10 ? "0" : "") + n; }
function mmss(ms){
  var s = Math.max(0, Math.ceil(ms/1000));
  return pad2(Math.floor(s/60)) + ":" + pad2(s%60);
}
function clock(ts){
  if(!ts) return "—";
  var d = new Date(ts);
  return pad2(d.getHours()) + ":" + pad2(d.getMinutes()) + ":" + pad2(d.getSeconds());
}
function teamCls(t){ return t === "A" ? "a" : (t === "B" ? "b" : "ref"); }
function tName(t){ return engine.sel.teamName(t); }

function showToast(msg, kind){
  var d = document.createElement("div");
  d.className = "toast" + (kind === "info" ? " info" : "");
  d.textContent = msg;
  toastHost.appendChild(d);
  setTimeout(function(){ d.remove(); }, 3200);
}
/* every intent goes to the server; a rejection is never silent */
function act(action, cb){
  if(!connected){ showToast("Reconnecting — action not sent.", "err"); return; }
  SOCKET.emit("action", action, function(res){
    if(res && res.ok === false) showToast(res.message || res.code, "err");
    if(cb) cb(res);
  });
}

/* ===================================================================
   SHARED COMPONENTS
   =================================================================== */
function matchHeaderHTML(){
  var s = S();
  return '<div class="match-header">' +
    '<div class="mh-meta">' + esc(s.id) + ' · ' + esc(statusLabel()) + '</div>' +
    '<div class="mh-side a"><div class="tag">TEAM A</div><div class="nm">' + esc(s.teamA.name) + '</div></div>' +
    '<div class="mh-mid"><div class="vs">VS</div><div class="fmt">' + esc(s.format) + '</div></div>' +
    '<div class="mh-side b"><div class="tag">TEAM B</div><div class="nm">' + esc(s.teamB.name) + '</div></div>' +
  '</div>';
}

function statusLabel(){
  var s = S();
  if(s.status === "TIMEOUT_WAITING_REFEREE") return "TIMEOUT — WAITING FOR REFEREE";
  return s.status.replace(/_/g, " ");
}

/* who is acting now, and what they must do — spec §30 */
function heroInfo(){
  var s = S(), step = engine.sel.stepDef();
  switch(true){
    case s.status === "SETUP":
      return { tone:"sys", team:"MATCH SETUP", act:"CONFIGURE THE MATCH TO BEGIN", sub:"Admin creates the match, then the toss decides the ban/pick order." };
    case s.status === "TOSS_1":
      return { tone:s.toss1.caller === "A" ? "team-a" : "team-b", team:tName(s.toss1.caller),
               act:"CALL HEAD OR TAIL", sub:"TOSS #1 — WINNER CHOOSES WHO STARTS BAN/PICK" };
    case s.status === "TOSS_1_CHOICE":
      return { tone:s.toss1.winner === "A" ? "team-a" : "team-b", team:tName(s.toss1.winner),
               act:"WINS THE TOSS — CHOOSE BAN/PICK ORDER", sub:"START FIRST, OR LET THE OPPONENT START" };
    case s.status === "TIMEOUT_WAITING_REFEREE":
      return { tone:"timeout", team:tName(s.timeout.team),
               act:"TIMEOUT — WARNING #" + s.timeout.warningNo,
               sub:"STEP " + s.timeout.step + " / " + s.sequence.length + " · WAITING FOR REFEREE CONFIRMATION" };
    case s.status.indexOf("VETO_STEP_") === 0 && !!step:
      return { tone:step.actor === "A" ? "team-a" : "team-b", team:tName(step.actor),
               act: step.action === "BAN" ? "BAN 1 MAP" : ("PICK 1 MAP — GAME " + step.game),
               sub:"STEP " + s.currentStep + " / " + s.sequence.length };
    case s.status === "RANDOM_MAP":
      return { tone:"sys", team:"REFEREE", act:"RANDOM MAP — GAME " + (step ? step.game : ""),
               sub:"STEP " + s.currentStep + " / " + s.sequence.length + " · " + engine.sel.available().length + " CANDIDATES" };
    case s.status === "SIDE_TOSS":
      return { tone:s.toss2.caller === "A" ? "team-a" : "team-b", team:tName(s.toss2.caller),
               act:"CHOOSE HEADS OR TAILS", sub:"TOSS #2 — WINNER CHOOSES SIDE FOR GAME 1" };
    case s.status === "SIDE_SELECTION":
      return { tone:s.toss2.winner === "A" ? "team-a" : "team-b", team:tName(s.toss2.winner),
               act:"TOSS WINNER — CHOOSE THE GAME 1 SIDE", sub:"THE OPPONENT RECEIVES THE OTHER SIDE" };
    case s.status === "SIDE_CONFIRMATION":
      return { tone:"sys", team:"GAME 1 SIDE SELECTION",
               act:tName("A") + ": " + s.gameSides[1].A + "  ·  " + tName("B") + ": " + s.gameSides[1].B,
               sub:"AWAITING REFEREE CONFIRMATION" };
    case s.status === "COMPLETED":
      return { tone:"sys", team:"MATCH VETO COMPLETE",
               act:"GAME 1 SIDE SELECTION CONFIRMED", sub:"ALL GAMES ASSIGNED · RESULT LOCKED" };
  }
  return { tone:"sys", team:"—", act:"—", sub:"" };
}

function heroHTML(){
  var i = heroInfo();
  return '<div class="hero ' + i.tone + '">' +
    '<div class="h-step">' + esc(i.sub) + '</div>' +
    '<div class="h-team">' + esc(i.team) + '</div>' +
    '<div class="h-act">' + esc(i.act) + '</div>' +
    timerHTML() +
  '</div>';
}

function timerVisible(){
  var s = S();
  return s.status.indexOf("VETO_STEP_") === 0 || s.status === "TIMEOUT_WAITING_REFEREE";
}
function timerHTML(){
  if(!timerVisible()) return "";
  var s = S();
  if(s.status === "TIMEOUT_WAITING_REFEREE"){
    return '<div class="timer-wrap"><div class="timer-lbl">TIME LIMIT ' + engine.TURN_SECONDS + ' SECONDS</div>' +
      '<div class="timer out">TIME OUT</div>' +
      '<div class="timer-note danger">WARNING #' + S().timeout.warningNo + ' · WAITING FOR REFEREE CONFIRMATION</div></div>';
  }
  return '<div class="timer-wrap"><div class="timer-lbl">TIME REMAINING</div>' +
    '<div class="timer" data-timer>' + mmss(remainingMs()) + '</div>' +
    '<div class="timer-note" data-timer-note></div></div>';
}
/* tick-only repaint: the single engine timer drives every visible clock (spec §11) */
function paintTimer(){
  var s = S(); if(!s) return;
  var ms = remainingMs();
  var secs = Math.ceil(ms/1000);
  var nodes = document.querySelectorAll("[data-timer]");
  for(var i=0;i<nodes.length;i++){
    var el = nodes[i];
    el.textContent = mmss(ms);
    el.classList.toggle("warn", s.timer.running && secs <= engine.WARN_AT && secs > engine.DANGER_AT);
    el.classList.toggle("danger", s.timer.running && secs <= engine.DANGER_AT);
  }
  var notes = document.querySelectorAll("[data-timer-note]");
  for(var j=0;j<notes.length;j++){
    var n = notes[j];
    n.className = "timer-note" + (secs <= engine.DANGER_AT ? " danger" : (secs <= engine.WARN_AT ? " warn" : ""));
    n.textContent = !s.timer.running ? "" :
      (secs <= engine.DANGER_AT ? secs + " SECONDS REMAINING" :
      (secs <= engine.WARN_AT ? engine.WARN_AT + " SECONDS REMAINING" : ""));
  }
}

/* ---------- map grid (spec §12) ---------- */
function mapCardHTML(m, opts){
  var s = S();
  opts = opts || {};
  var selectable = !!opts.selectable && m.status === "AVAILABLE";
  var chosen = opts.selectable && s.selection === m.id;
  var cand = opts.markCandidates && m.status === "AVAILABLE";
  var badge = m.status;
  if(chosen) badge = "SELECTED";
  var cls = "map-card" + (selectable ? " selectable" : "") + (chosen ? " chosen" : "") + (cand ? " cand" : "");
  var gameTag = m.assignedGame ? '<div class="mc-game">GAME ' + m.assignedGame + '</div>' : "";
  var img = MAP_IMAGES[m.id];
  var thumb = img
    ? '<img src="' + img + '" alt="' + esc(m.name) + '">'
    : '<span class="ph">&#9678;</span>';
  return '<div class="' + cls + '" data-st="' + m.status + '" data-map="' + m.id + '"' +
      (selectable ? ' data-act="selectMap"' : "") + '>' +
    '<div class="mc-num">' + pad2(opts.index + 1) + '</div>' +
    '<div class="mc-badge">' + esc(badge) + '</div>' + gameTag +
    '<div class="map-thumb">' + thumb + '</div>' +
    '<div class="mc-name">' + esc(m.name) + '</div>' +
  '</div>';
}
function mapGridHTML(opts){
  var s = S();
  return '<div class="map-grid' + (ui.rolling ? " shuffling" : "") + '" id="mapGrid">' +
    s.mapPool.map(function(m, i){
      var o = Object.assign({}, opts || {}); o.index = i; return mapCardHTML(m, o);
    }).join("") + '</div>';
}

/* ---------- games result panel (spec §18) ---------- */
function gamesPanelHTML(){
  var s = S(), n = engine.sel.gamesCount(), out = [];
  for(var g=1; g<=n; g++){
    var mapId = s.gameMaps[g];
    var m = mapId ? engine.sel.mapById(mapId) : null;
    var isRandom = m && m.status === "RANDOM";
    var sides = s.gameSides[g];
    var sidesHTML;
    if(sides){
      var pendTag = (g === 1 && !s.toss2.confirmed) ? '<div class="s-pend">PENDING CONFIRMATION</div>' : '';
      sidesHTML = '<div class="gb-sides">' + pendTag +
        '<div class="s-row"><span>' + esc(s.teamA.shortName) + '</span><span class="' + (sides.A === "RED" ? "s-red" : "s-blue") + '">' + sides.A + '</span></div>' +
        '<div class="s-row"><span>' + esc(s.teamB.shortName) + '</span><span class="' + (sides.B === "RED" ? "s-red" : "s-blue") + '">' + sides.B + '</span></div>' +
      '</div>';
    } else if(g === 1){
      sidesHTML = '<div class="gb-sides"><div class="s-pend">SIDE TOSS PENDING</div></div>';
    } else {
      /* FINAL RULE 2 — Games 2-5 side selection is deliberately NOT implemented here.
         The tournament rule (loser of the previous map chooses) is handled off-system. */
      sidesHTML = '<div class="gb-sides"><div class="s-pend">HANDLED OUTSIDE SYSTEM</div></div>';
    }
    out.push('<div class="game-box ' + (isRandom ? "rnd" : (m ? "filled" : "")) + '">' +
      '<div class="gb-lbl">GAME ' + g + '</div>' +
      '<div class="gb-map' + (m ? "" : " gb-tbd") + '">' + (m ? esc(m.name) : "TBD") + '</div>' +
      '<div class="gb-src">' + (m ? (isRandom ? "RANDOM" : (m.byTeam ? tName(m.byTeam) + " PICK" : "PICK")) : "&nbsp;") + '</div>' +
      sidesHTML +
    '</div>');
  }
  var html = '<div class="games">' + out.join("") + '</div>';
  if(n > 1){
    html += '<div class="notice" style="border-color:var(--border);background:var(--panel-2)">' +
      '<div class="n-tag" style="color:var(--muted)">SCOPE</div>' +
      '<div class="n-body" style="color:var(--muted)">Game 2–' + n + ' side selection is handled outside this system. ' +
      'This system only controls the Game 1 side selection.</div></div>';
  }
  if(s.status === "COMPLETED"){
    var unused = s.mapPool.filter(function(m){ return m.status === "AVAILABLE"; });
    html += '<div class="unused-wrap"><div class="lbl">UNUSED MAPS — ' + unused.length + '</div>' +
      '<div class="unused-list">' + (unused.length
        ? unused.map(function(m){ return '<span class="unused-pill">' + esc(m.name) + '</span>'; }).join("")
        : '<span class="unused-pill">NONE</span>') + '</div></div>';
  }
  return html;
}

/* ---------- referee timeline (spec §15) ---------- */
function timelineHTML(){
  var s = S();
  if(!s.sequence.length) return '<div class="empty">TIMELINE APPEARS AFTER TOSS #1 DECIDES THE FIRST-ACTION TEAM</div>';
  return '<div class="timeline">' + s.sequence.map(function(st){
    var done = st.n < s.currentStep || (st.n === s.currentStep && st.action === "RANDOM" && s.random.confirmed);
    var isCur = st.n === s.currentStep && !done;
    var timedOut = s.status === "TIMEOUT_WAITING_REFEREE" && s.timeout && s.timeout.step === st.n;
    var rec = null;
    for(var i = s.auditLog.length - 1; i >= 0; i--){
      var a = s.auditLog[i];
      if(a.step === st.n && (a.action === "BAN" || a.action === "PICK" || a.action === "RANDOM") && a.map){ rec = a; break; }
    }
    var cls = timedOut ? "timeout" : (done ? "done" : (isCur ? "current" : "pending"));
    var mark = timedOut ? "!" : (done ? "✓" : (isCur ? "●" : "○"));
    var who = st.actor === "REFEREE" ? "REFEREE" : tName(st.actor);
    var verb = st.action === "RANDOM" ? "RANDOM MAP" : (st.action + (st.game ? " → GAME " + st.game : ""));
    var res = rec ? esc(rec.map) : (timedOut ? "TIMEOUT" : (isCur ? "WAITING" : "—"));
    return '<div class="tl-row ' + cls + '">' +
      '<div class="tl-mark">' + mark + '</div>' +
      '<div class="tl-step">STEP ' + pad2(st.n) + '</div>' +
      '<div class="tl-body"><span class="tl-team ' + teamCls(st.actor) + '">' + esc(who) + '</span> &mdash; ' + esc(verb) + '</div>' +
      '<div class="tl-res">' + res + '</div>' +
    '</div>';
  }).join("") + '</div>';
}

/* ---------- audit log (spec §22) ---------- */
function auditHTML(){
  var s = S();
  if(!s.auditLog.length) return '<div class="empty">NO ACTIONS RECORDED YET</div>';
  return '<div class="audit">' + s.auditLog.slice().reverse().map(function(a){
    var kind = a.status === "TIMEOUT" ? "timeout"
             : a.action === "BAN" ? "ban"
             : a.action === "PICK" ? "pick"
             : a.action === "RANDOM" ? "random" : "sys";
    var who = a.team ? '<b class="' + teamCls(a.team) + '">' + esc(a.teamName) + '</b>' : '<b class="ref">SYSTEM</b>';
    var dur = (a.timerStart && a.timerEnd) ? (Math.round((a.timerEnd - a.timerStart)/1000) + "s") : "";
    return '<div class="au-row' + (a.status === "TIMEOUT" ? " is-timeout" : "") + '">' +
      '<div class="au-step">' + (a.step ? "STEP " + pad2(a.step) : "—") + '</div>' +
      '<div class="au-main">' + who +
        '<span class="au-act ' + kind + '">' + esc(a.status === "TIMEOUT" ? "TIMEOUT" : a.action) + '</span>' +
        esc(a.map || a.result || "") + '</div>' +
      '<div class="au-meta">' + clock(a.timestamp) + (dur ? " · " + dur : "") + '<br>' + esc(a.role) + '</div>' +
    '</div>';
  }).join("") + '</div>';
}

/* ---------- rule-consistency notices (spec §34) ---------- */
function configNotices(){
  var s = S(), out = [];
  var enabled = s.mapPool.filter(function(m){ return m.status !== "DISABLED"; }).length;
  if(s.status !== "SETUP"){
    var afterSix = enabled - 6;   // steps 1-6 always consume exactly 6 maps, in both formats
    var expect = engine.EXPECTED_REMAINING[s.format];
    if(afterSix !== expect){
      out.push({ tag:"CONFIGURATION REQUIRED — MAP POOL SIZE",
        body:"The " + s.format + " rule expects " + expect + " maps to remain before the final random draw. " +
             "Steps 1–6 consume 6 maps, so this " + enabled + "-map pool leaves " + afterSix + ". " +
             "A full " + (expect + 6) + "-map pool is required for the official sequence — re-enable maps in the setup screen, " +
             "or treat this as a referee decision. The engine does not guess: it draws from whatever is actually AVAILABLE and records the real count." });
    }
  }
  if(s.status === "RANDOM_MAP"){
    var actual = engine.sel.available().length;
    var exp2 = engine.EXPECTED_REMAINING[s.format];
    if(actual !== exp2){
      out.push({ tag:"CONFIGURATION REQUIRED — RANDOM POOL",
        body:"Rule expects " + exp2 + " candidate map(s) at this step; " + actual + " are actually AVAILABLE. Referee decision required before confirming." });
    }
  }
  return out;
}
function noticesHTML(){
  return configNotices().map(function(n){
    return '<div class="notice"><div class="n-tag">' + esc(n.tag) + '</div><div class="n-body">' + esc(n.body) + '</div></div>';
  }).join("");
}

/* ---------- coin block ---------- */
function faceLabel(v){ return v === "HEAD" ? "HEADS" : (v === "TAIL" ? "TAILS" : v); }
function coinHTML(tossNo){
  var s = S(), t = tossNo === 1 ? s.toss1 : s.toss2;
  var val = t.result ? ("Toss Result: " + faceLabel(t.result)) : (ui.coinSpin && ui.coinSpin.active ? "TOSSING COIN…" : "NOT TOSSED YET");
  var sub = t.result ? ("WINNER: " + tName(t.winner)) : (t.call ? (tName(t.caller) + " CALLED: " + t.call) : "");
  return '<div class="coin-area">' +
    '<div class="coin-scene"><div class="coin" id="coin' + tossNo + '">' +
      '<div class="coin-face front">HEADS</div><div class="coin-face back">TAILS</div>' +
    '</div></div>' +
    '<div class="coin-read"><div class="cr-v">' + esc(val) + '</div><div class="cr-s">' + esc(sub) + '</div></div>' +
  '</div>';
}
function spinCoin(tossNo, result){
  var el = document.getElementById("coin" + tossNo);
  if(!el || !el.animate) return;
  var deg = result === "HEAD" ? 1800 : 1980;
  el.animate([{ transform:"rotateY(0deg)" }, { transform:"rotateY(" + deg + "deg)" }],
             { duration:2000, easing:"cubic-bezier(.2,.7,.2,1)", fill:"forwards" });
}

/* ===================================================================
   VIEW: CAPTAIN (spec §13)
   =================================================================== */
function renderCaptain(myTeam){
  var s = S(), step = engine.sel.stepDef();
  var out = matchHeaderHTML() + heroHTML();
  var isMyTurn = false, actionWord = "";

  if(s.status === "TOSS_1" && s.toss1.caller === myTeam && !s.toss1.call){
    out += '<div class="panel"><div class="panel-head"><h2>Toss #1 — Your Call</h2></div><div class="panel-body">' +
      coinHTML(1) + '<div class="choice-row">' +
      '<button class="choice-btn" data-act="toss1Call" data-call="HEAD">HEADS<small>หัว</small></button>' +
      '<button class="choice-btn" data-act="toss1Call" data-call="TAIL">TAILS<small>ก้อย</small></button>' +
      '</div></div></div>';
  } else if(s.status === "TOSS_1_CHOICE" && s.toss1.winner === myTeam && !s.toss1.choice){
    out += '<div class="panel"><div class="panel-head"><h2>You Won The Toss — Choose Ban/Pick Order</h2></div><div class="panel-body">' +
      '<div class="choice-row">' +
      '<button class="choice-btn" data-act="toss1Choice" data-choice="FIRST">START FIRST<small>your team acts on step 1</small></button>' +
      '<button class="choice-btn" data-act="toss1Choice" data-choice="SECOND">OPPONENT STARTS<small>opponent acts on step 1</small></button>' +
      '</div></div></div>';
  } else if(s.status === "SIDE_TOSS" && s.toss2.caller === myTeam && !s.toss2.call){
    out += '<div class="panel"><div class="panel-head"><h2>Toss #2 — Side Toss</h2></div><div class="panel-body">' +
      coinHTML(2) + '<div class="choice-row">' +
      '<button class="choice-btn" data-act="toss2Call" data-call="HEAD">HEADS<small>หัว</small></button>' +
      '<button class="choice-btn" data-act="toss2Call" data-call="TAIL">TAILS<small>ก้อย</small></button>' +
      '</div></div></div>';
  } else if(s.status === "SIDE_SELECTION" && s.toss2.winner === myTeam && !s.toss2.side){
    out += '<div class="panel"><div class="panel-head"><h2>Select Your Side — Game 1</h2></div><div class="panel-body">' +
      '<div class="side-grid">' +
      '<button class="side-btn red" data-act="selectSide" data-side="RED"><span class="em">🔴</span><span class="ti">RED SIDE</span><span class="su">บุกก่อน</span></button>' +
      '<button class="side-btn blue" data-act="selectSide" data-side="BLUE"><span class="em">🔵</span><span class="ti">BLUE SIDE</span><span class="su">รับก่อน</span></button>' +
      '</div></div></div>';
  } else if(s.status === "SIDE_CONFIRMATION"){
    var cs = s.gameSides[1];
    out += '<div class="panel"><div class="panel-head"><h2>Game 1 Side Selection</h2>' +
      '<span class="chip warn">AWAITING REFEREE CONFIRMATION</span></div><div class="panel-body">' +
      '<div class="kv"><span class="k">' + esc(s.teamA.name) + '</span><span class="v" style="color:var(--' + (cs.A === "RED" ? "red" : "blue") + ')">' + cs.A + '</span></div>' +
      '<div class="kv"><span class="k">' + esc(s.teamB.name) + '</span><span class="v" style="color:var(--' + (cs.B === "RED" ? "red" : "blue") + ')">' + cs.B + '</span></div>' +
      '<div class="empty" style="margin-top:8px">WAITING FOR THE REFEREE TO CONFIRM &amp; LOCK THE RESULT</div>' +
      '</div></div>';
  }

  if(s.status.indexOf("VETO_STEP_") === 0 && step && step.actor === myTeam){
    isMyTurn = true;
    actionWord = step.action === "BAN" ? "CONFIRM BAN" : "CONFIRM PICK";
  }

  /* map board — selectable only on this captain's own turn (spec §14, §32) */
  out += '<div class="panel"><div class="panel-head"><h2>Map Pool</h2>' +
    '<span class="chip ' + (isMyTurn ? "active" : "") + '">' +
      (isMyTurn ? "YOUR TURN — SELECT A MAP" : (s.status === "TIMEOUT_WAITING_REFEREE" ? "LOCKED — WAITING FOR REFEREE" : "VIEW ONLY")) +
    '</span></div><div class="panel-body">' + mapGridHTML({ selectable: isMyTurn }) ;

  if(isMyTurn){
    var selName = s.selection ? engine.sel.mapById(s.selection).name : null;
    out += '<div class="confirm-bar">' +
      '<div class="cb-txt"><small>SELECTED MAP</small>' + esc(selName || "— none —") + '</div>' +
      '<button class="btn btn-primary btn-xl" data-act="confirmAction"' + (selName ? "" : " disabled") + '>' + actionWord + '</button>' +
    '</div>';
  }
  out += '</div></div>';

  out += '<div class="panel"><div class="panel-head"><h2>Match Result</h2>' +
    '<span class="chip">' + esc(S().format) + '</span></div><div class="panel-body">' + gamesPanelHTML() + '</div></div>';
  return out;
}

/* ===================================================================
   VIEW: REFEREE / ADMIN CONTROL (spec §15, §16, §17)
   =================================================================== */
function renderReferee(){
  var s = S(), step = engine.sel.stepDef();
  var out = matchHeaderHTML() + heroHTML() + noticesHTML();

  /* --- toss controls --- */
  if(s.status === "TOSS_1" || s.status === "TOSS_1_CHOICE"){
    out += '<div class="panel"><div class="panel-head"><h2>Toss #1 — Ban/Pick Priority</h2>' +
      '<span class="chip active">STEP 0</span></div><div class="panel-body">' + coinHTML(1);
    if(s.status === "TOSS_1"){
      out += '<div class="notice ref"><div class="n-tag">REFEREE</div><div class="n-body">' +
        (s.toss1.call
          ? esc(tName("A")) + " called " + esc(s.toss1.call) + ". Flip the coin when both teams are ready."
          : "Waiting for " + esc(tName("A")) + " (top of bracket) to call HEAD or TAIL. The referee may also call on their behalf below.") +
        '</div></div>';
      if(!s.toss1.call){
        out += '<div class="choice-row">' +
          '<button class="choice-btn" data-act="toss1Call" data-call="HEAD" data-as="A">HEADS<small>call for ' + esc(tName("A")) + '</small></button>' +
          '<button class="choice-btn" data-act="toss1Call" data-call="TAIL" data-as="A">TAILS<small>call for ' + esc(tName("A")) + '</small></button>' +
        '</div>';
      }
      out += '<div class="btn-row" style="margin-top:14px">' +
        '<button class="btn btn-primary btn-xl" data-act="toss1Flip"' + (s.toss1.call ? "" : " disabled") + '>FLIP COIN</button></div>';
    } else {
      out += '<div class="notice ref"><div class="n-tag">WAITING</div><div class="n-body">' +
        esc(tName(s.toss1.winner)) + ' won the toss and must choose whether to start the ban/pick. ' +
        'The referee may record the choice on their behalf.</div></div>' +
        '<div class="choice-row">' +
        '<button class="choice-btn" data-act="toss1Choice" data-choice="FIRST" data-as="W">' + esc(tName(s.toss1.winner)) + ' STARTS<small>acts on step 1</small></button>' +
        '<button class="choice-btn" data-act="toss1Choice" data-choice="SECOND" data-as="W">OPPONENT STARTS<small>' + esc(tName(s.toss1.winner === "A" ? "B" : "A")) + ' acts on step 1</small></button>' +
        '</div>';
    }
    out += '</div></div>';
  }

  /* --- FINAL RULE 1: timeout -> warning -> referee confirmation --- */
  if(s.status === "TIMEOUT_WAITING_REFEREE"){
    out += '<div class="panel" style="border-color:var(--danger)"><div class="panel-head">' +
      '<h2>Timeout — Warning #' + s.timeout.warningNo + '</h2>' +
      '<span class="chip danger">WAITING FOR REFEREE CONFIRMATION</span></div><div class="panel-body">' +
      '<div class="kv"><span class="k">Team</span><span class="v ' + teamCls(s.timeout.team) + '">' + esc(tName(s.timeout.team)) + '</span></div>' +
      '<div class="kv"><span class="k">Action</span><span class="v">' + esc(s.timeout.action) + '</span></div>' +
      '<div class="kv"><span class="k">Step</span><span class="v">' + s.timeout.step + ' / ' + s.sequence.length + '</span></div>' +
      '<div class="kv"><span class="k">Time Limit</span><span class="v">' + engine.TURN_SECONDS + ' SECONDS</span></div>' +
      '<div class="kv"><span class="k">Warning Issued</span><span class="v" style="color:var(--danger)">#' + s.timeout.warningNo + '</span></div>' +
      '<div class="kv"><span class="k">Total Warnings</span><span class="v">' +
        esc(s.teamA.shortName) + ': ' + s.warnings.A + ' &nbsp;·&nbsp; ' + esc(s.teamB.shortName) + ': ' + s.warnings.B + '</span></div>' +
      '<div class="kv"><span class="k">Status</span><span class="v" style="color:var(--danger)">WAITING FOR REFEREE CONFIRMATION</span></div>' +
      '<div class="notice"><div class="n-tag">NO PENALTY APPLIED</div><div class="n-body">' +
        'No map was selected, banned or picked, and no forfeit was applied. ' +
        esc(tName(s.timeout.team)) + ' resumes the same step with a fresh ' + engine.TURN_SECONDS +
        ' seconds once the referee confirms the warning.</div></div>' +
      '<div class="btn-row" style="margin-top:14px">' +
        '<button class="btn btn-primary btn-xl" data-act="refConfirmWarning">CONFIRM WARNING &amp; CONTINUE</button>' +
      '</div>' +
      '</div></div>';
  }

  /* --- random map (spec §17) --- */
  if(s.status === "RANDOM_MAP"){
    var cands = engine.sel.available();
    out += '<div class="panel" style="border-color:var(--gold)"><div class="panel-head">' +
      '<h2>Random Map — Game ' + (step ? step.game : "") + '</h2>' +
      '<span class="chip warn">' + cands.length + ' CANDIDATES</span></div><div class="panel-body">' +
      '<div class="lbl">CANDIDATE MAPS (AVAILABLE ONLY)</div>' +
      '<div class="unused-list" style="margin-bottom:14px">' + cands.map(function(m){
        return '<span class="unused-pill">' + esc(m.name) + '</span>'; }).join("") + '</div>';
    if(!s.random.result){
      out += '<button class="btn btn-primary btn-xl" data-act="randomStart">RANDOMIZE</button>';
    } else if(s.random.rolling){
      out += '<div class="empty">RANDOMIZING…</div>';
    } else if(!s.random.confirmed){
      var rm = engine.sel.mapById(s.random.result);
      out += '<div class="final-hero" style="margin-bottom:14px"><div class="fh-l">GAME ' + step.game + ' — RANDOM MAP</div>' +
        '<div class="fh-t" style="color:var(--gold)">' + esc(rm.name).toUpperCase() + '</div></div>' +
        '<div class="btn-row"><button class="btn btn-primary btn-xl" data-act="randomConfirm">CONFIRM &amp; LOCK RESULT</button></div>';
    }
    out += '</div></div>';
  }

  /* --- FINAL RULES 3 & 4: Toss #2, dedicated referee screen --- */
  if(s.status === "SIDE_TOSS" || s.status === "SIDE_SELECTION" || s.status === "SIDE_CONFIRMATION"){
    var caller = s.toss2.caller, otherT = (caller === "A" ? "B" : "A");
    var gs1 = s.gameSides[1];
    var phaseChip = s.status === "SIDE_TOSS" ? (s.toss2.call ? "STEP 2 — PERFORM TOSS" : "STEP 1 — COIN CALL")
                  : s.status === "SIDE_SELECTION" ? "STEP 3 — WINNER CHOOSES SIDE"
                  : "STEP 5 — AWAITING CONFIRMATION";
    out += '<div class="panel" style="border-color:var(--accent)"><div class="panel-head">' +
      '<h2>Toss #2 — Game 1 Side Selection</h2>' +
      '<span class="chip active">' + phaseChip + '</span>' +
      '</div><div class="panel-body">' +
      '<div class="kv"><span class="k">First Coin Caller</span><span class="v ' + teamCls(caller) + '">' + esc(tName(caller)) + '</span></div>' +
      '<div class="kv"><span class="k">Step 1 — Coin Call</span><span class="v muted">' + esc(tName(caller)) + ' has the right to choose Heads or Tails first' +
        (s.toss2.call ? ' &rarr; <b style="color:var(--accent)">' + faceLabel(s.toss2.call) + '</b> · ' + esc(tName(otherT)) +
          ' gets <b>' + faceLabel(s.toss2.call === "HEAD" ? "TAIL" : "HEAD") + '</b>' : '') + '</span></div>' +
      '<div class="kv"><span class="k">Step 2 — Perform Toss #2</span><span class="v muted">' +
        (s.toss2.result ? 'Toss Result: <b style="color:var(--gold)">' + faceLabel(s.toss2.result) + '</b>' : 'pending') + '</span></div>' +
      '<div class="kv"><span class="k">Step 3 — Toss Winner</span><span class="v ' + (s.toss2.winner ? teamCls(s.toss2.winner) : "muted") + '">' +
        (s.toss2.winner ? esc(tName(s.toss2.winner)) : "pending") + '</span></div>' +
      '<div class="kv"><span class="k">Step 4 — Side Assignment</span><span class="v muted">' +
        (gs1 ? esc(tName("A")) + ' — <b style="color:var(--' + (gs1.A === "RED" ? "red" : "blue") + ')">' + gs1.A + '</b> · ' +
               esc(tName("B")) + ' — <b style="color:var(--' + (gs1.B === "RED" ? "red" : "blue") + ')">' + gs1.B + '</b>'
             : 'pending') + '</span></div>' +
      coinHTML(2);
    if(s.status === "SIDE_TOSS"){
      if(!s.toss2.call){
        out += '<div class="choice-row">' +
          '<button class="choice-btn" data-act="toss2Call" data-call="HEAD" data-as="C">HEADS<small>call for ' + esc(tName(s.toss2.caller)) + '</small></button>' +
          '<button class="choice-btn" data-act="toss2Call" data-call="TAIL" data-as="C">TAILS<small>call for ' + esc(tName(s.toss2.caller)) + '</small></button>' +
        '</div>';
      }
      out += '<div class="btn-row" style="margin-top:14px">' +
        '<button class="btn btn-primary btn-xl" data-act="toss2Flip"' + (s.toss2.call ? "" : " disabled") + '>PERFORM TOSS #2</button></div>';
    } else if(s.status === "SIDE_SELECTION"){
      out += '<div class="final-hero" style="margin:14px 0"><div class="fh-l">TOSS WINNER</div>' +
        '<div class="fh-t" style="color:var(--' + (s.toss2.winner === "A" ? "teamA" : "teamB") + ')">' + esc(tName(s.toss2.winner)) + '</div>' +
        '<div class="gb-src" style="margin-top:6px">' + esc(tName(s.toss2.winner)) + ' may choose the Game 1 side</div></div>' +
        '<div class="side-grid">' +
        '<button class="side-btn red" data-act="selectSide" data-side="RED" data-as="W"><span class="em">🔴</span><span class="ti">RED SIDE</span><span class="su">บุกก่อน</span></button>' +
        '<button class="side-btn blue" data-act="selectSide" data-side="BLUE" data-as="W"><span class="em">🔵</span><span class="ti">BLUE SIDE</span><span class="su">รับก่อน</span></button>' +
        '</div>';
    } else {
      /* Step 5 — referee confirmation, nothing is locked until this is pressed */
      out += '<div class="final-hero" style="margin:14px 0"><div class="fh-l">GAME 1 SIDE SELECTION</div>' +
        '<div class="fh-t" style="font-size:clamp(17px,3.2vw,24px);margin-top:10px;line-height:1.6">' +
          esc(tName("A")) + ' — <span style="color:var(--' + (gs1.A === "RED" ? "red" : "blue") + ')">' + gs1.A + '</span><br>' +
          esc(tName("B")) + ' — <span style="color:var(--' + (gs1.B === "RED" ? "red" : "blue") + ')">' + gs1.B + '</span>' +
        '</div></div>' +
        '<div class="btn-row"><button class="btn btn-primary btn-xl" data-act="confirmSideLock">CONFIRM &amp; LOCK</button></div>';
    }
    out += '</div></div>';
  }

  /* --- final result --- */
  if(s.status === "COMPLETED") out += finalResultHTML();

  /* --- always-on operational panels --- */
  out += '<div class="two-col">' +
    '<div class="panel" style="margin-top:0"><div class="panel-head"><h2>Veto Timeline</h2>' +
      '<span class="chip">' + (s.sequence.length ? ("STEP " + Math.min(s.currentStep, s.sequence.length) + " / " + s.sequence.length) : "NOT STARTED") + '</span>' +
      '</div><div class="panel-body">' + timelineHTML() + '</div></div>' +
    '<div class="panel" style="margin-top:0"><div class="panel-head"><h2>Match State</h2></div><div class="panel-body">' +
      '<div class="kv"><span class="k">Match ID</span><span class="v">' + esc(s.id) + '</span></div>' +
      '<div class="kv"><span class="k">Format</span><span class="v">' + esc(s.format) + '</span></div>' +
      '<div class="kv"><span class="k">Status</span><span class="v">' + esc(statusLabel()) + '</span></div>' +
      '<div class="kv"><span class="k">Toss #1</span><span class="v muted">' + (s.toss1.result
          ? esc(s.toss1.caller === "A" ? "A" : "B") + " called " + esc(s.toss1.call) + " · " + esc(s.toss1.result)
          : "pending") + '</span></div>' +
      '<div class="kv"><span class="k">Toss #1 Winner</span><span class="v ' + teamCls(s.toss1.winner) + '">' + (s.toss1.winner ? esc(tName(s.toss1.winner)) : "—") + '</span></div>' +
      '<div class="kv"><span class="k">First Action</span><span class="v ' + teamCls(s.firstActionTeam) + '">' + (s.firstActionTeam ? esc(tName(s.firstActionTeam)) : "—") + '</span></div>' +
      '<div class="kv"><span class="k">Toss #2 Winner</span><span class="v ' + teamCls(s.toss2.winner) + '">' + (s.toss2.winner ? esc(tName(s.toss2.winner)) : "—") + '</span></div>' +
      '<div class="kv"><span class="k">Warnings</span><span class="v">' +
        '<span class="' + (s.warnings.A ? "" : "muted") + '" style="' + (s.warnings.A ? "color:var(--danger)" : "") + '">' +
          esc(s.teamA.shortName) + ': ' + s.warnings.A + '</span> &nbsp;·&nbsp; ' +
        '<span class="' + (s.warnings.B ? "" : "muted") + '" style="' + (s.warnings.B ? "color:var(--danger)" : "") + '">' +
          esc(s.teamB.shortName) + ': ' + s.warnings.B + '</span></span></div>' +
      '<div class="kv"><span class="k">Available Maps</span><span class="v">' + engine.sel.available().length + '</span></div>' +
      '<div class="kv"><span class="k">Banned</span><span class="v">' + s.mapPool.filter(function(m){ return m.status === "BANNED"; }).length + '</span></div>' +
      '<div class="kv"><span class="k">Picked</span><span class="v">' + s.mapPool.filter(function(m){ return m.status === "PICKED" || m.status === "RANDOM"; }).length + '</span></div>' +
      '<div class="btn-row" style="margin-top:14px"><button class="btn btn-danger btn-block" data-act="resetMatch">RESET MATCH</button></div>' +
    '</div></div>' +
  '</div>';

  out += '<div class="panel"><div class="panel-head"><h2>Map Pool</h2>' +
    '<span class="chip">' + s.mapPool.filter(function(m){ return m.status !== "DISABLED"; }).length + ' IN POOL</span>' +
    '</div><div class="panel-body">' + mapGridHTML({ markCandidates: s.status === "RANDOM_MAP" }) + '</div></div>';

  out += '<div class="panel"><div class="panel-head"><h2>Match Result</h2></div><div class="panel-body">' + gamesPanelHTML() + '</div></div>';
  out += '<div class="panel"><div class="panel-head"><h2>Audit Log</h2>' +
    '<span class="chip">' + s.auditLog.length + ' RECORDS</span>' +
    (sel.roleCanReferee(ui.role) ? '<button class="btn" data-act="exportLog">EXPORT JSON</button>' : '') + '</div>' +
    '<div class="panel-body">' + auditHTML() + '</div></div>';
  return out;
}

/* ---------- final result screen (spec §35) ---------- */
function finalResultHTML(){
  var s = S();
  return '<div class="panel" style="border-color:var(--gold)"><div class="panel-head">' +
    '<h2>Match Veto Complete</h2><span class="chip warn">LOCKED</span></div><div class="panel-body">' +
    '<div class="final-hero"><div class="fh-l">MAP VETO RESULT — ' + esc(s.format) + '</div>' +
      '<div class="fh-t">' + esc(s.teamA.name) + ' <span style="color:var(--muted)">vs</span> ' + esc(s.teamB.name) + '</div></div>' +
    gamesPanelHTML() +
    '<div class="btn-row" style="margin-top:16px">' +
      '<button class="btn btn-primary" data-act="exportLog">DOWNLOAD VETO LOG (JSON)</button>' +
    '</div></div></div>';
}

/* ===================================================================
   VIEW: PUBLIC LIVE (spec §20)
   =================================================================== */
function renderPublic(){
  var s = S();
  var out = matchHeaderHTML() + heroHTML();
  if(s.status === "COMPLETED"){
    out += '<div class="panel" style="border-color:var(--gold)"><div class="panel-head"><h2>Final Veto Result</h2>' +
      '<span class="chip warn">LOCKED</span></div><div class="panel-body">' + gamesPanelHTML() + '</div></div>';
  } else {
    out += '<div class="panel"><div class="panel-head"><h2>Game Assignments</h2>' +
      '<span class="chip">' + esc(s.format) + '</span></div><div class="panel-body">' + gamesPanelHTML() + '</div></div>';
  }
  out += '<div class="panel"><div class="panel-head"><h2>Map Pool</h2>' +
    '<span class="chip">' + engine.sel.available().length + ' AVAILABLE · ' +
      s.mapPool.filter(function(m){ return m.status === "BANNED"; }).length + ' BANNED</span>' +
    '</div><div class="panel-body">' + mapGridHTML({}) + '</div></div>';
  out += '<div class="panel"><div class="panel-head"><h2>Veto History</h2></div><div class="panel-body">' + auditHTML() + '</div></div>';
  return out;
}

/* ===================================================================
   VIEW: OBS BROADCAST (spec §21)
   =================================================================== */
function renderObs(){
  var s = S(), i = heroInfo();
  var toneColor = i.tone === "team-a" ? "var(--teamA)" : (i.tone === "team-b" ? "var(--teamB)" : (i.tone === "timeout" ? "var(--danger)" : "var(--fg)"));
  var out = '<div class="obs">' +
    '<div class="obs-teams"><div class="ot a">' + esc(s.teamA.name) + '</div>' +
      '<div class="ovs">VS</div><div class="ot b">' + esc(s.teamB.name) + '</div></div>' +
    '<div class="obs-hero"><div class="oh-lbl">' + esc(s.format) + ' · ' + esc(i.sub || "MAP VETO") + '</div>' +
      '<div class="oh-team" style="color:' + toneColor + '">' + esc(i.team) + '</div>' +
      '<div class="oh-act" style="color:' + toneColor + '">' + esc(i.act) + '</div></div>';
  if(timerVisible()){
    out += s.status === "TIMEOUT_WAITING_REFEREE"
      ? '<div class="obs-timer" style="color:var(--danger);font-size:clamp(34px,8vw,66px)">TIME OUT</div>'
      : '<div class="obs-timer" data-timer>' + mmss(s.timer.remainingMs) + '</div><div data-timer-note style="display:none"></div>';
  }
  out += '<div class="obs-maps">' + s.mapPool.map(function(m){
    return '<div class="obs-map" data-st="' + m.status + '">' + esc(m.name) + '</div>'; }).join("") + '</div>';
  var n = engine.sel.gamesCount(), g = [];
  for(var k=1;k<=n;k++){
    var mid = s.gameMaps[k], mm = mid ? engine.sel.mapById(mid) : null;
    g.push('<div class="obs-game ' + (mm ? "has" : "") + '"><div class="og-l">GAME ' + k + '</div>' +
      '<div class="og-m">' + (mm ? esc(mm.name) : "TBD") + '</div></div>');
  }
  out += '<div class="obs-games">' + g.join("") + '</div></div>';
  return out;
}

/* ===================================================================
   ROLE BAR + DEMO BAR
   =================================================================== */
/* ===================================================================
   RENDER DISPATCH
   =================================================================== */
function render(){
  var s = S();
  document.body.classList.toggle("obs-mode", ui.role === "OBS");
  renderStatusBar();
  if(!s){
    app.innerHTML = '<div class="wrap"><div class="panel"><div class="panel-body">' +
      '<div class="empty">' + (connected ? "LOADING MATCH…" : "CONNECTING…") + '</div></div></div></div>';
    return;
  }
  var html;
  if(ui.role === "OBS"){
    app.innerHTML = renderObs();
  } else {
    if(ui.role === "CAPTAIN_A"){ html = renderCaptain("A"); }
    else if(ui.role === "CAPTAIN_B"){ html = renderCaptain("B"); }
    else if(ui.role === "PUBLIC"){ html = renderPublic(); }
    else { html = renderReferee(); }
    app.innerHTML = '<div class="wrap">' + html +
      '<footer class="ft">PB REAL-TIME MAP VETO — ROOM ' + esc(ui.roomId || "") +
      ' · ' + esc((CONST.ROLES[ui.role] || {}).label || ui.role) + '</footer></div>';
  }
  paintTimer();
}

/* a thin connection/role bar: who you are and whether the link is live */
function renderStatusBar(){
  if(ui.role === "OBS"){ statusHost.innerHTML = ""; return; }
  var cls = connected ? "ok" : "danger";
  var label = connected ? "LIVE" : "RECONNECTING…";
  statusHost.innerHTML = '<div class="rolebar">' +
    '<span class="proto-tag" style="border-color:var(--' + (connected ? "ok" : "danger") + ');color:var(--' +
      (connected ? "ok" : "danger") + ')">' + label + '</span>' +
    '<span class="rb-label">You are</span>' +
    '<span class="chip ' + (ui.role === "CAPTAIN_A" ? "" : ui.role === "CAPTAIN_B" ? "" : "active") + '" style="' +
      (ui.role === "CAPTAIN_A" ? "background:var(--red-soft);color:var(--teamA)" :
       ui.role === "CAPTAIN_B" ? "background:var(--blue-soft);color:var(--teamB)" : "") + '">' +
      esc(roleDisplayName()) + '</span>' +
    '<span class="rb-label" style="margin-left:auto">ROOM ' + esc(ui.roomId || "") + '</span>' +
  '</div>';
}
function roleDisplayName(){
  var s = S();
  if(s && ui.role === "CAPTAIN_A") return s.teamA.name;
  if(s && ui.role === "CAPTAIN_B") return s.teamB.name;
  return (CONST.ROLES[ui.role] || {}).label || ui.role;
}

/* ===================================================================
   EVENT DELEGATION
   =================================================================== */
document.addEventListener("click", function(e){
  var el = e.target.closest ? e.target.closest("[data-act]") : null;
  if(!el) return;
  var a = el.getAttribute("data-act");
  var s = S();

  switch(a){

    /* --- toss #1 --- */
    case "toss1Call":
      act({ type:"TOSS1_CALL", call:el.getAttribute("data-call") }); return;
    case "toss1Flip": {
      var r = act({ type:"TOSS1_FLIP" });
      if(r && r.ok !== false){ ui.coinSpin = { toss:1, active:true }; spinCoin(1, S().toss1.result); }
      return;
    }
    case "toss1Choice":
      act({ type:"TOSS1_CHOICE", choice:el.getAttribute("data-choice") }); return;

    /* --- veto --- */
    case "selectMap":
      act({ type:"SELECT_MAP", mapId:el.getAttribute("data-map") }); return;
    case "confirmAction":
      act({ type:"CONFIRM_ACTION" }); return;

    /* --- referee timeout --- */
    case "refConfirmWarning": act({ type:"REFEREE_CONFIRM_WARNING" }); return;

    /* --- random --- */
    case "randomStart": {
      var rr = act({ type:"RANDOM_START" });
      if(rr && rr.ok !== false) runRandomAnimation();
      return;
    }
    case "randomConfirm": act({ type:"RANDOM_CONFIRM" }); return;

    /* --- toss #2 / side --- */
    case "toss2Call": act({ type:"TOSS2_CALL", call:el.getAttribute("data-call") }); return;
    case "toss2Flip": {
      var r2 = act({ type:"TOSS2_FLIP" });
      if(r2 && r2.ok !== false){ ui.coinSpin = { toss:2, active:true }; spinCoin(2, S().toss2.result); }
      return;
    }
    case "selectSide": act({ type:"SELECT_SIDE", side:el.getAttribute("data-side") }); return;
    case "confirmSideLock": act({ type:"CONFIRM_SIDE_LOCK" }); return;

    /* --- match --- */
    case "exportServerLog": downloadLog(); return;
    case "exportLog": downloadLog(); return;

  }
});

/* ---------- random map animation (spec §17) ---------- */
function runRandomAnimation(){
  var s = S();
  if(!s || !s.random || !s.random.candidates.length) return;
  if(ui.rolling) return;                       // already running on this client
  var cands = s.random.candidates.slice();
  ui.rolling = true;
  render();
  var delay = 80, elapsed = 0, target = 3400, prev = null;
  function clearPrev(){
    if(prev){ var p = document.querySelector('[data-map="' + prev + '"]'); if(p) p.classList.remove("rolling"); }
  }
  function tick(){
    var cur = S();
    /* the server has settled the draw — stop and let the real result render */
    if(!cur || !cur.random.rolling){ ui.rolling = false; clearPrev(); render(); return; }
    if(!ui.rolling){ clearPrev(); return; }
    clearPrev();
    var id = cands[Math.floor(Math.random()*cands.length)];
    var node = document.querySelector('[data-map="' + id + '"]');
    if(node) node.classList.add("rolling");
    prev = id;
    if(elapsed >= target){
      /* only the referee tells the server the spin is over; everyone else
         simply stops when the settled state arrives */
      if(sel.roleCanReferee(ui.role)) act({ type:"RANDOM_SETTLE" });
      else setTimeout(tick, 200);
      return;
    }
    elapsed += delay;
    delay = Math.min(delay*1.12, 300);
    setTimeout(tick, delay);
  }
  setTimeout(tick, delay);
}


/* ---------- export (spec §35) ---------- */
function downloadLog(){
  if(!ui.roomId || !ui.token){ showToast("No access token.", "err"); return; }
  var url = "/api/match/" + encodeURIComponent(ui.roomId) + "/log?t=" + encodeURIComponent(ui.token);
  var a = document.createElement("a");
  a.href = url; a.download = (S() ? S().id : "match") + "-veto-log.json";
  document.body.appendChild(a); a.click(); a.remove();
  showToast("Veto log requested from the server.", "info");
}

/* ===================================================================
   BOOTSTRAP — join the room with the token from the link
   =================================================================== */
(function boot(){
  var parts = location.pathname.split("/").filter(Boolean);
  ui.roomId = (parts[1] || "").toUpperCase();
  ui.token = new URLSearchParams(location.search).get("t") || "";
  render();

  function join(){
    SOCKET.emit("join", { roomId: ui.roomId, token: ui.token }, function(res){
      if(!res || !res.ok){
        app.innerHTML = '<div class="wrap"><div class="panel" style="border-color:var(--danger)">' +
          '<div class="panel-head"><h2>Cannot open this match</h2></div><div class="panel-body">' +
          '<div class="empty" style="color:var(--danger)">' + esc((res && res.error) || "Unknown error") + '</div>' +
          '<div class="empty">Check that you are using the full link that the referee sent you.</div>' +
          '</div></div></div>';
        return;
      }
      ui.role = res.role;
      applyState(res.state);
    });
  }

  function applyState(payload){
    if(!payload) return;
    state = payload.match;
    if(payload.serverTime) serverOffset = payload.serverTime - Date.now();
    render();
  }

  /* read-only hooks for automated testing; this is the client's own view only */
  window.__sock = SOCKET;
  window.__pbremaining = remainingMs;
  Object.defineProperty(window, "__pbstate", { get: function(){ return state; } });
  Object.defineProperty(window, "__pbrole",  { get: function(){ return ui.role; } });
  Object.defineProperty(window, "__pbconn",  { get: function(){ return connected; } });

  SOCKET.on("connect", function(){ connected = true; join(); });
  SOCKET.on("disconnect", function(){ connected = false; renderStatusBar(); });
  SOCKET.on("state", applyState);
  SOCKET.on("event", function(ev){
    if(!ev) return;
    /* coin + random animations are driven by server events so every screen sees them */
    if(ev.type === "TOSS_COMPLETED"){
      var t = ev.payload.toss;
      setTimeout(function(){ spinCoin(t, ev.payload.result); }, 20);
    }
    if(ev.type === "RANDOM_MAP_STARTED"){ runRandomAnimation(); }
  });

  /* one local ticker drives every visible clock, always from the server deadline */
  setInterval(function(){ if(state) paintTimer(); }, 200);
})();

})();
